-- Mullny Photos catalog restore. Generated by scripts/restore-plan; do not edit by hand.
--
-- Order (foreign keys): categories, albums, photos, url_history, then one cover update.
-- albums.cover_photo_id points at photos, so albums are inserted without a cover and the cover is
-- set at the end, after the photos exist.
--
-- Triggers: every catalog table carries user triggers (updated_at stamps, the pending-changes counter,
-- the cover check, slug history). A restore must keep the original timestamps and must not bump or
-- rewrite anything, so they are switched off for the run: alter table ... disable trigger user.
-- That switches off only non-system triggers; foreign keys stay enforced. It needs table ownership
-- (the postgres role in the Supabase SQL editor). Whether the SQL editor allows it is still to be
-- verified on a scratch project (see docs/VERIFY.md). If it is refused, remove the disable and enable
-- lines and use this fallback instead. Only the triggers that fire during this script matter:
-- the insert-time bump_pending triggers and the updated_at stamp on albums (hit by the cover update).
--
--   drop trigger categories_bump_pending on public.categories;
--   drop trigger albums_bump_pending on public.albums;
--   drop trigger photos_bump_pending on public.photos;
--   drop trigger url_history_bump_pending on public.url_history;
--   drop trigger albums_set_updated_at on public.albums;
--   -- ... run the inserts and the cover update below, then recreate exactly as migration
--   -- 20261019100300_triggers.sql defines them:
--   create trigger categories_bump_pending after insert or update or delete on public.categories
--     for each row execute function public.bump_pending();
--   create trigger albums_bump_pending after insert or update or delete on public.albums
--     for each row execute function public.bump_pending();
--   create trigger photos_bump_pending after insert or update or delete on public.photos
--     for each row execute function public.bump_pending();
--   create trigger url_history_bump_pending after insert or update or delete on public.url_history
--     for each row execute function public.bump_pending();
--   create trigger albums_set_updated_at before update on public.albums
--     for each row execute function public.set_updated_at();
--
-- Idempotency: every insert is on conflict (id) do nothing, so running the script twice changes
-- nothing the second time. It never deletes. The only updates are the cover update (only where the
-- album has no cover yet) and the site_state marker. A row that clashes on another unique key
-- (slug, master_key, old_path) under a different id stops the script and the transaction rolls back.
--
-- Finally site_state.pending_changes is raised to at least 1 so the admin offers one publish.

begin;

alter table public.categories disable trigger user;
alter table public.albums disable trigger user;
alter table public.photos disable trigger user;
alter table public.url_history disable trigger user;

insert into public.categories (id, slug, name, description, seo_title, seo_description, sort, visible, created_at, updated_at)
values
  ('00000000-0000-4000-8000-000000000001', 'svatby', 'Svatby', 'Zlatý déšť; "ok"', null, null, 10, true, '2026-10-19T12:00:00.000Z', '2026-10-19T12:00:00.000Z'),
  ('00000000-0000-4000-8000-000000000002', 'portrety', 'O''Brien & syn', null, null, null, 20, false, '2026-10-19T12:00:00.000Z', '2026-10-19T12:00:00.000Z')
on conflict (id) do nothing;

