  ('00000000-0000-4000-8000-000000000012', '00000000-0000-4000-8000-000000000002', 'bez-fotek', 'Bez fotek', null, null, null, null, null, 20, false, null, '2026-10-19T12:00:00.000Z', '2026-10-19T12:00:00.000Z')
