dva', 10, null, '2026-10-19T12:00:00.000Z', '2026-10-19T12:00:00.000Z'),
  ('00000000-0000-4000-8000-000000000032', '00000000-0000-4000-8000-000000000011', 'photos/00000000-0000-4000-8000-000000000032/master.jpg', 3000, 2000, '{"master":{"w":3000,"h":2000,"bytes":1000},"webp":[{"tier":480,"w":480,"h":320,"bytes":20}],"jpeg":{"w":1600,"h":1067,"bytes":300},"og":{"w":1200,"h":630,"bytes":100}}'::jsonb, 1420, '#aabbcc', 'Pár na louce', null, 20, null, '2026-10-19T12:00:00.000Z', '2026-10-19T12:00:00.000Z')
