  ('00000000-0000-4000-8000-000000000042', '/svatby/smazano/', null, 410, '2026-10-19T12:00:00.000Z')
on conflict (id) do nothing;

update public.albums set cover_photo_id = '00000000-0000-4000-8000-000000000032' where id = '00000000-0000-4000-8000-000000000011' and cover_photo_id is null;

alter table public.categories enable trigger user;
alter table public.albums enable trigger user;
alter table public.photos enable trigger user;
alter table public.url_history enable trigger user;

update public.site_state set pending_changes = greatest(pending_changes, 1);

